import 'dart:io';import 'dart:convert';import 'dart:typed_data';import 'package:crypto/crypto.dart';import 'package:path/path.dart' as path;
/// PVIC is a transparent carrier package: it stores the image and payload together
/// in an explicit, documented package (not steganographic pixel hiding).
class CarrierPackage {
 static const magic='PVIC01';
 static Future<File> create(File carrier,File payload,String outputPath) async {final image=await carrier.readAsBytes(), data=await payload.readAsBytes();final metadata=jsonEncode({'carrierName':path.basename(carrier.path),'payloadName':path.basename(payload.path),'carrierLength':image.length,'payloadLength':data.length,'carrierSha256':sha256.convert(image).toString(),'payloadSha256':sha256.convert(data).toString()});final meta=utf8.encode(metadata);final out=BytesBuilder();out.add(utf8.encode(magic));out.add(_u32(meta.length));out.add(meta);out.add(image);out.add(data);final target=File(outputPath);await target.writeAsBytes(await out.toBytes());return target;}
 static Future<Map<String,File>> extract(File packageFile,String outputDirectory) async {final bytes=await packageFile.readAsBytes();final b=Uint8List.fromList(bytes);if(bytes.length<10||utf8.decode(b.sublist(0,6))!=magic)throw FormatException('Not a PixelVault carrier package');final ml=_read32(b,6);if(10+ml>bytes.length)throw FormatException('Invalid package header');final meta=jsonDecode(utf8.decode(b.sublist(10,10+ml)));final start=10+ml, il=meta['carrierLength'] as int,pl=meta['payloadLength'] as int;if(start+il+pl!=bytes.length)throw FormatException('Package size mismatch');final image=b.sublist(start,start+il),payload=b.sublist(start+il);if(sha256.convert(image).toString()!=meta['carrierSha256']||sha256.convert(payload).toString()!=meta['payloadSha256'])throw FormatException('Integrity check failed');final dir=Directory(outputDirectory);await dir.create(recursive:true);final f1=File(path.join(dir.path,path.basename(meta['carrierName'] as String)));final f2=File(path.join(dir.path,path.basename(meta['payloadName'] as String)));await f1.writeAsBytes(image);await f2.writeAsBytes(payload);return {'carrier':f1,'payload':f2};}
 static List<int> _u32(int n)=>[n>>24&255,n>>16&255,n>>8&255,n&255];static int _read32(Uint8List b,int i)=>(b[i]<<24)|(b[i+1]<<16)|(b[i+2]<<8)|b[i+3];
}
